import { Injectable } from '@angular/core'

@Injectable({
  providedIn: 'root',
})
export class IndexedDbService {
  private db!: IDBDatabase
  private opened = false

  async open() {
    if(this.opened) return
    if(typeof window === 'undefined' || !window.indexedDB) return

    this.opened = true

    return new Promise<void>((resolve, reject) => {
      const req = window.indexedDB.open('front-sql', 1)

      req.onupgradeneeded = () => {
        const db = req.result

        // tables store
        if (!db.objectStoreNames.contains('tables')) 
          db.createObjectStore('tables')

        // files store
        if (!db.objectStoreNames.contains('files')) {
          const fileStore = db.createObjectStore('files', {
            keyPath: 'id'
          })
          // index by database/table for faster queries
          fileStore.createIndex('by_table', 'tableRef')
        }
      }

      req.onsuccess = () => {
        this.db = req.result
        resolve()
      }

      req.onerror = () => reject(req.error)
    })
  }

  async saveTable(name: string, data: any): Promise<void> {
    return new Promise((resolve, reject) => {
      if (!this.db) return resolve()  
      const tx = this.db.transaction('tables', 'readwrite')
      tx.objectStore('tables').put(data, name)
      tx.oncomplete = () => resolve()
      tx.onerror = () => reject(tx.error)
    })
  }  

  async loadTable(name: string): Promise<any> {
    return new Promise(resolve => {
      if (!this.db) return resolve(null)
      const tx = this.db.transaction('tables')
      const req = tx.objectStore('tables').get(name)
      req.onsuccess = () => resolve(req.result)
    })
  }

  async deleteTable(name: string): Promise<void> {
    return new Promise((resolve, reject) => {
      if (!this.db) return resolve()
      const tx = this.db.transaction('tables', 'readwrite')
      const store = tx.objectStore('tables')
      store.delete(name)
      tx.oncomplete = () => resolve()
      tx.onerror = () => reject(tx.error)
      tx.onabort = () => reject(tx.error)
    })
  }  

  async tableExists(name: string): Promise<boolean> {
    return new Promise(resolve => {
      if (!this.db) return resolve(false)
      const tx = this.db.transaction('tables', 'readonly')
      const req = tx.objectStore('tables').get(name)
  
      req.onsuccess = () => resolve(!!req.result)
      req.onerror = () => resolve(false)
    })
  }  

  async iterateKeys(cb: (key: IDBValidKey) => void): Promise<void> {
    return new Promise(resolve => {
      const tx = this.db.transaction('tables')
      const store = tx.objectStore('tables')
      const req = store.openCursor()
  
      req.onsuccess = () => {
        const cursor = req.result
        if (!cursor) return resolve()
        cb(cursor.key)
        cursor.continue()
      }
    })
  }
  
  async deleteByPrefix(prefix: string) {
    const tx = this.db.transaction('tables', 'readwrite')
    const store = tx.objectStore('tables')
    const req = store.openCursor() 
    
    req.onsuccess = () => {
      const cursor = req.result
      if (!cursor) return
  
      const key = cursor.key
      if (typeof key === 'string' && key.startsWith(prefix)) 
        cursor.delete()

      cursor.continue()
    }
  }  

  async saveFile (file: any): Promise<void> {
    return new Promise((resolve, reject) => {
      if (!this.db) return resolve()  
      const tx = this.db.transaction('files', 'readwrite')
      tx.objectStore('files').put(file)
      tx.oncomplete = () => resolve()
      tx.onerror = () => reject(tx.error)
    })
  }

  async deleteFile(id: string): Promise<void> {  
    return new Promise((resolve, reject) => {
      if (!this.db) return resolve()
      const tx = this.db.transaction('files', 'readwrite')
      tx.objectStore('files').delete(id)
      tx.oncomplete = () => resolve()
      tx.onerror = () => reject(tx.error)
      tx.onabort = () => reject(tx.error)
    })
  }

  async loadFile(id: string): Promise<any> {
    return new Promise(resolve => {
      if (!this.db) return resolve(null)
      const tx = this.db.transaction('files', 'readonly')
      const req = tx.objectStore('files').get(id)
      req.onsuccess = () => resolve(req.result)
    })
  }

  async loadFilesByTable(tableRef: string): Promise<any> {
    return new Promise(resolve => {
      if (!this.db) return resolve(null)
      const tx = this.db.transaction('files', 'readonly')
      const index = tx.objectStore('files').index('by_table')
      const req = index.getAll(tableRef)
      req.onsuccess = () => resolve(req.result)
    })
  }
}