import { Token, TokenType } from './sql-token'
import { SQL_KEYWORDS } from './sql-keywords'

export class SqlLexer {
  private pos = 0

  constructor(private input: string) {}

  tokenize(): Token[] {
    const tokens: Token[] = []

    while (true) {
      const token = this.nextToken()
      tokens.push(token)

      if (token.type === TokenType.EOF) 
        break
    }
    return tokens
  }

  private nextToken(): Token {
    this.skipWhitespace()
  
    const start = this.pos

    if (this.pos >= this.input.length) 
      return this.makeToken(TokenType.EOF, '', start)
  
    const ch = this.input[this.pos]
  
    // single-line comment
    if (ch === '-' && this.peek() === '-') {
      this.skipSingleLineComment()
      return this.nextToken()
    }
    // multi-line comment
    if (ch === '/' && this.peek() === '*') {
      this.skipMultiLineComment()
      return this.nextToken()
    }
  
    if (this.isLetter(ch)) 
      return this.readIdentifierOrKeyword()
  
    if (this.isDigit(ch)) 
      return this.readNumber()
  
    if (ch === `'`) 
      return this.readString()
  
    // comparison operators
    if (ch === '=') 
        return this.readOperator()
    
    if (ch === '!' && this.peek() === '=') 
        return this.readOperator()
    
    if (ch === '<' || ch === '>') 
        return this.readOperator()

    switch (ch) {
      case ',':
        this.pos++
        return this.makeToken(TokenType.COMMA, ',', start)
  
      case '*':
        this.pos++
        return this.makeToken(TokenType.STAR, '*', start)
  
      case '(':
        this.pos++
        return this.makeToken(TokenType.LPAREN, '(', start)
  
      case ')':
        this.pos++
        return this.makeToken(TokenType.RPAREN, ')', start)
      
       case '.':
        this.pos++
        return this.makeToken(TokenType.DOT, '.', start)
    }
  
    throw new Error(`Unexpected character '${ch}' at position ${this.pos}`)
  }

  private skipWhitespace() {
    while (this.pos < this.input.length && /\s/.test(this.input[this.pos])) 
      this.pos++
  }
  
  private isLetter(ch: string) {
    return /[a-z_]/i.test(ch)
  }
  
  private isDigit(ch: string) {
    return /\d/.test(ch)
  }
  
  // inspect the next character
  private peek(offset = 1): string {
    return this.input[this.pos + offset] ?? ''
  }
  
  private readOperator(): Token {
    const start = this.pos
    let value = this.input[this.pos]
  
    if ((value === '!' || value === '<' || value === '>') &&
      this.peek() === '='
    ) {
      value += '='
      this.pos += 2
    } else {
      this.pos++
    }
  
    return this.makeToken(TokenType.OPERATOR, value, start)
  }  

  private readIdentifierOrKeyword(): Token {
    const start = this.pos
  
    while (
      this.pos < this.input.length &&
      /[a-z0-9_]/i.test(this.input[this.pos])
    ) {
      this.pos++
    }
  
    const raw = this.input.slice(start, this.pos)
    const upper = raw.toUpperCase()

    // logical operators
    if (upper === 'AND' || upper === 'OR') 
      return this.makeToken(TokenType.OPERATOR, upper, start)

    // NULL literal
    if (upper === 'NULL')
      return this.makeToken(TokenType.NULL, null, start)
   
    const type = SQL_KEYWORDS.has(upper) ? TokenType.KEYWORD : TokenType.IDENTIFIER
    
    return this.makeToken(type, upper, start)
  }

  private readNumber(): Token {
    const start = this.pos
    let hasDot = false
  
    while (this.pos < this.input.length) {
      const ch = this.input[this.pos]
  
      if (ch === '.') {  // decimal numbers
        if (hasDot) break
        hasDot = true
        this.pos++
        continue
      }
  
      if (!/\d/.test(ch)) break
      this.pos++
    }

    const value = this.input.slice(start, this.pos)

    if (value === '.') throw new Error(`Invalid number at position ${start}`)

    return this.makeToken(TokenType.NUMBER, value, start)
  }  

  private readString(): Token {
    const start = this.pos
    this.pos++ // skip opening '
  
    let value = ''
  
    while (this.pos < this.input.length) {
      const ch = this.input[this.pos]
  
      // escaped single quote: ''
      if (ch === "'" && this.peek() === "'") {
        value += "'"
        this.pos += 2
        continue
      }
  
      // closing quote
      if (ch === "'") {
        this.pos++
        return this.makeToken(TokenType.STRING, value, start)
      }
  
      value += ch
      this.pos++
    }
  
    throw new Error(`Unterminated string literal at ${start}`)
  }  

  private makeToken(type: TokenType, value: string | null, start: number): Token {
    return {
      type,
      value,
      start,
      end: this.pos
    }
  }

  private skipSingleLineComment() {
    this.pos += 2 // skip --
  
    while (
      this.pos < this.input.length &&
      this.input[this.pos] !== '\n'
    ) {
      this.pos++
    }
  }
  
  private skipMultiLineComment() {
    this.pos += 2 // skip /*
  
    while (this.pos < this.input.length) {
      if (
        this.input[this.pos] === '*' &&
        this.peek() === '/'
      ) {
        this.pos += 2 // skip */
        return
      }
      this.pos++
    }  

    throw new Error('Unterminated multi-line comment')
  }  
}