import { Token, TokenType } from '../lexer/sql-token'
import { ExprParser } from './expr-parser'

import {
    SqlStatement,
    CreateDatabaseStmt,
    UseDatabaseStmt,
    DropDatabaseStmt,
    CreateTableStmt,
    DescribeTableStmt,
    DropTableStmt,
    AlterAction,
    AlterTableStmt,
    InsertStmt,
    SelectStmt,
    UpdateStmt,
    DeleteStmt,
    SelectColumn,
    JoinClause,
    FromClause
  } from './sql-ast'
  
export class SqlParser {
    private pos = 0

    constructor(private tokens: Token[]) {}

    parse(): SqlStatement {
      const token = this.current()
    
      if (token.type !== TokenType.KEYWORD)
        throw new Error(`Unexpected token: ${token.value}`)      
    
      switch (token.value) {
        case 'SELECT':
          return this.parseSelect()
    
        case 'INSERT':
          return this.parseInsert()
    
        case 'UPDATE':
          return this.parseUpdate()
    
        case 'DELETE':
          return this.parseDelete()
    
        case 'CREATE':
          return this.parseCreate()
    
        case 'DESCRIBE':
          return this.parseDescribe()

        case 'USE':
          return this.parseUse()
    
        case 'DROP':
          return this.parseDrop()
    
        case 'SHOW':
          return this.parseShow()

        case 'ALTER':
          return this.parseAlter()
          
        default:
          throw new Error(`Unsupported statement: ${token.value}`)
      }
    }    
  
    private parseCreate(): SqlStatement {
      this.expectKeyword('CREATE')
    
      if (this.match(TokenType.KEYWORD, 'DATABASE')) {
        const name = this.expectIdentifier()
    
        const stmt: CreateDatabaseStmt = {
          kind: 'CREATE_DATABASE',
          name
        }
    
        return stmt
      }
    
      if (this.match(TokenType.KEYWORD, 'TABLE')) 
        return this.parseCreateTable()

      throw new Error('Unsupported CREATE statement')
    }
    
    private parseCreateTable(): CreateTableStmt {
      const table = this.expectIdentifier()
    
      this.expect(TokenType.LPAREN)
    
      const columns: {
        name: string
        datatype: string
        primary: boolean
        unique: boolean
        autoIncrement: boolean
      }[] = []
    
      do {
        const name = this.expectIdentifier()
    
        const datatype = this.expectIdentifier()
    
        let primary = false
        let unique = false
        let autoIncrement = false
    
        if (this.match(TokenType.KEYWORD, 'PRIMARY')) {
          // this.expectKeyword('KEY')
          primary = true
        }
    
        if (this.match(TokenType.KEYWORD, 'UNIQUE')) {
          unique = true
        }
    
        if (this.match(TokenType.KEYWORD, 'AUTO_INCREMENT')) {
          autoIncrement = true
        }

        columns.push({
          name,
          datatype,
          primary,
          unique,
          autoIncrement
        })
    
      } while (this.match(TokenType.COMMA))
    
      this.expect(TokenType.RPAREN)
    
      return {
        kind: 'CREATE_TABLE',
        table,
        columns
      }
    }
    
    private parseAlter(): AlterTableStmt {
      this.expectKeyword('ALTER')
      this.expectKeyword('TABLE')

      const table = this.expectIdentifier()

      const actions: AlterAction[] = []

      do {

        if (this.match(TokenType.KEYWORD, 'ADD')) {
          this.expectKeyword('COLUMN')

          const name = this.expectIdentifier()
          const datatype = this.expectIdentifier()

          let primary = false
          let unique = false

          if (this.match(TokenType.KEYWORD, 'PRIMARY')) {
            // this.expectKeyword('KEY')
            primary = true
          }

          if (this.match(TokenType.KEYWORD, 'UNIQUE')) {
            unique = true
          }

          actions.push({
            type: 'ADD_COLUMN',
            column: {
              name,
              type: datatype as any,
              primary,
              unique
            }
          })

        } else if (this.match(TokenType.KEYWORD, 'DROP')) {
          this.expectKeyword('COLUMN')

          const column = this.expectIdentifier()

          actions.push({
            type: 'DROP_COLUMN',
            column
          })

        } else if (this.match(TokenType.KEYWORD, 'RENAME')) {

          if (this.match(TokenType.KEYWORD, 'COLUMN')) {
            const from = this.expectIdentifier()
            this.expectKeyword('TO')
            const to = this.expectIdentifier()

            actions.push({
              type: 'RENAME_COLUMN',
              from,
              to
            })

          } else if (this.match(TokenType.KEYWORD, 'TO')) {
            const to = this.expectIdentifier()

            actions.push({
              type: 'RENAME_TABLE',
              to
            })

          } else throw new Error('Invalid RENAME syntax')
          

        } else throw new Error('Unsupported ALTER TABLE action')        

      } while (this.match(TokenType.COMMA))

      return {
        kind: 'ALTER_TABLE',
        table,
        actions
      }
    }
    
    private parseUse(): UseDatabaseStmt {
      this.expectKeyword('USE')
    
      const name = this.expectIdentifier()
    
      return {
        kind: 'USE_DATABASE',
        name
      }
    }
    
    private parseDrop(): SqlStatement {
      this.expectKeyword('DROP')
    
      if (this.match(TokenType.KEYWORD, 'DATABASE')) {
        const name = this.expectIdentifier()
    
        const stmt: DropDatabaseStmt = {
          kind: 'DROP_DATABASE',
          name
        }
    
        return stmt
      }
    
      if (this.match(TokenType.KEYWORD, 'TABLE')) {
        const table = this.expectIdentifier()
    
        const stmt: DropTableStmt = {
          kind: 'DROP_TABLE',
          table
        }
    
        return stmt
      }
    
      throw new Error('Unsupported DROP statement')
    }
    
    private parseShow(): SqlStatement {
      this.expectKeyword('SHOW')
    
      if (this.match(TokenType.KEYWORD, 'DATABASES')) {
        return {
          kind: 'SHOW_DATABASES'
        }
      }
    
      if (this.match(TokenType.KEYWORD, 'TABLES')) {
        return {
          kind: 'SHOW_TABLES'
        }
      }
    
      throw new Error('Unsupported SHOW statement')
    }
    
    private parseDescribe(): SqlStatement {
      this.expectKeyword('DESCRIBE')
    
      if (this.match(TokenType.KEYWORD, 'TABLE')) {
        const table = this.expectIdentifier()
    
        const stmt: DescribeTableStmt = {
          kind: 'DESCRIBE_TABLE',
          table
        }
    
        return stmt
      }
    
      throw new Error('Unsupported DESCRIBE statement')
    }
    
    private current(): Token {
      return this.tokens[this.pos]
    }

    private advance(): Token {
      return this.tokens[this.pos++]
    }
    
    private match(type: TokenType, value?: string): boolean {
      const token = this.current()
      if (token.type !== type) return false
      if (value && token.value !== value) return false
      this.advance()
      return true
    }

    private expect(type: TokenType, value?: string): Token {
      const token = this.current()
    
      if (token.type !== type || (value && token.value !== value)) {
        throw new Error(
          `Expected ${value ?? TokenType[type]}, got ${token.value}`
        )
      }    
      return this.advance()
    }

    private expectKeyword(value: string): Token {
      return this.expect(TokenType.KEYWORD, value)
    }
    
    private expectIdentifier(): string {
      return this.expect(TokenType.IDENTIFIER).value
    }

    private parseInsert(): InsertStmt {
      this.expectKeyword('INSERT')
      this.expectKeyword('INTO')
    
      const table = this.expectIdentifier()
    
      // column list is defined
      let columns: string[] | null = null

      if (this.match(TokenType.LPAREN)) {
        columns = []

        do {
          const column = this.expectIdentifier()
          columns.push(column)
        } while (this.match(TokenType.COMMA))

        this.expect(TokenType.RPAREN)
      }

      this.expectKeyword('VALUES')
      this.expect(TokenType.LPAREN)
    
      const values: any[] = []
    
      do {
        const expr = this.parseValue()
        values.push(expr)
      } while (this.match(TokenType.COMMA))
    
      this.expect(TokenType.RPAREN)
    
      // safety check if columns are defined
      if (columns && columns.length !== values.length) {
        throw new Error(
          `Column count (${columns.length}) does not match value count (${values.length})`
        )
      }

      return {
        kind: 'INSERT',
        table,
        columns,
        values
      }
    }    
   
    private parseValue(): any {
      const token = this.current()
    
      switch (token.type) {
        case TokenType.NUMBER:
          this.advance()
          return Number(token.value)
    
        case TokenType.STRING:
          this.advance()
          return token.value
    
        case TokenType.KEYWORD:
          if (token.value === 'NULL') {
            this.advance()
            return null
          }
      }
    
      throw new Error(`Invalid value: ${token.value}`)
    }

    private parseUpdate(): UpdateStmt {
      this.expectKeyword('UPDATE')
      const table = this.expectIdentifier()
    
      this.expectKeyword('SET')
    
      const set: Record<string, any> = {}
    
      do {
        const column = this.expectIdentifier()
        this.expect(TokenType.OPERATOR, '=')
        set[column] = this.parseValue()
      } while (this.match(TokenType.COMMA))
    
      let where
    
      if (this.match(TokenType.KEYWORD, 'WHERE')) {
        where = this.parseWhereExpression()
      } else {
        throw new Error('UPDATE without WHERE is not allowed')
      }
    
      return {
        kind: 'UPDATE',
        table,
        set,
        where
      }
    }    
    
    private parseDelete(): DeleteStmt {
      this.expectKeyword('DELETE')
      this.expectKeyword('FROM')

      const table = this.expectIdentifier()

      if (!this.match(TokenType.KEYWORD, 'WHERE')) 
        throw new Error('DELETE without WHERE is not allowed')

      const where = this.parseWhereExpression()

      return {
        kind: 'DELETE',
        table,
        where
      }
    }

    private parseSelect(): SelectStmt {
      this.expectKeyword('SELECT')

      const distinct = this.match(TokenType.KEYWORD, 'DISTINCT')      
      const columns = this.parseColumnList()

      this.expectKeyword('FROM')

      const table = this.expectIdentifier()

      let alias: string | undefined

      if (this.match(TokenType.KEYWORD, 'AS')) {
        alias = this.expectIdentifier()
      }
      else if (this.current().type === TokenType.IDENTIFIER) {
        alias = this.advance().value
      }

      const from: FromClause = { table, alias }
      const joins: JoinClause[] = []

      while (this.current().type === TokenType.KEYWORD &&
            (this.current().value === 'INNER' || 
            this.current().value === 'LEFT' || 
            this.current().value === 'RIGHT' || 
            this.current().value === 'FULL' ||
            this.current().value === 'CROSS')
      ) {
        const joinType = this.advance().value as 'INNER' | 'LEFT' | 'RIGHT' | 'FULL' | 'CROSS'

        // Optionally consume OUTER
        if (this.current().value === 'OUTER') {
          this.advance()
        }
        
        this.expectKeyword('JOIN')

        const joinTable = this.expectIdentifier()

        let joinAlias: string | undefined

        if (this.match(TokenType.KEYWORD, 'AS')) {
          joinAlias = this.expectIdentifier()
        }
        else if (this.current().type === TokenType.IDENTIFIER) {
          joinAlias = this.advance().value
        }

        this.expectKeyword('ON')

        const on = this.parseWhereExpression()

        joins.push({
          type: joinType,
          table: joinTable,
          alias: joinAlias,
          on
        })
      }

      let where

      if (this.match(TokenType.KEYWORD, 'WHERE')) {
        where = this.parseWhereExpression()
      }
      
      let groupBy: string[] | undefined

      if (this.match(TokenType.KEYWORD, 'GROUP')) {
        this.expectKeyword('BY')
        groupBy = []
        do {
          groupBy.push(this.expectIdentifier())
        } while (this.match(TokenType.COMMA, ','))
      }

      let having

      if (this.match(TokenType.KEYWORD, 'HAVING')) {
        having = this.parseWhereExpression()
      }

      let orderBy

      if (this.match(TokenType.KEYWORD, 'ORDER')) {
        this.expectKeyword('BY')
        orderBy = this.parseOrderBy()
      }

      let limit: number | undefined
      let offset: number | undefined

      if (this.match(TokenType.KEYWORD, 'LIMIT')) {
        const limitToken = this.expect(TokenType.NUMBER)
        limit = Number(limitToken.value)

        if (this.match(TokenType.KEYWORD, 'OFFSET')) {
          const offsetToken = this.expect(TokenType.NUMBER)
          offset = Number(offsetToken.value)
        }
      }

      return {
        kind: 'SELECT',
        from,
        joins: joins.length ? joins : undefined,
        columns,
        where,
        distinct,
        orderBy,
        limit,
        offset,
        groupBy,
        having
      }
    }
  
    private parseColumnList(): SelectColumn[] {
      const columns: SelectColumn[] = []
    
      do {    
        // Aggregate functions
        if (
          this.current().type === TokenType.KEYWORD &&
          ['COUNT', 'SUM', 'AVG', 'MIN', 'MAX'].
          includes(this.current().value.toUpperCase())
        ) {
          const func = this.advance().value.toUpperCase()
    
          this.expect(TokenType.LPAREN)
    
          let argument: string | '*'    
          if (this.match(TokenType.STAR, '*')) 
            argument = '*'
          else
            argument = this.expectIdentifier()
    
          this.expect(TokenType.RPAREN)
    
          let alias: string | undefined

          if (this.match(TokenType.KEYWORD, 'AS')) {
            alias = this.expectIdentifier()
          }
          else if (this.current().type === TokenType.IDENTIFIER) {
            alias = this.advance().value
          }

          columns.push({
            type: func,
            argument,
            alias
          })
    
          continue
        }
    
        // SELECT *
        if (this.match(TokenType.STAR, '*')) {
          columns.push({ type: 'COLUMN', name: '*' })
          break
        }

        const name = this.expectIdentifier()

        let alias: string | undefined

        if (this.match(TokenType.KEYWORD, 'AS')) {
          alias = this.expectIdentifier()
        }
        else if (this.current().type === TokenType.IDENTIFIER) {
          alias = this.advance().value
        }

        columns.push({
          type: 'COLUMN',
          name,
          alias
        })
    
      } while (this.match(TokenType.COMMA))

      return columns
    }    
    
    private parseWhereExpression() {
      const exprTokens: Token[] = []
    
      while (
        this.current().type !== TokenType.EOF &&
        !this.isClauseBoundary()
      ) {
        exprTokens.push(this.advance())
      }
    
      exprTokens.push({
        type: TokenType.EOF,
        value: '',
        start: this.current().end,
        end: this.current().end
      })
    
      return new ExprParser(exprTokens).parse()
    } 

    private isClauseBoundary(): boolean {
      const token = this.current()
    
      if (token.type !== TokenType.KEYWORD)
        return false
    
      return [
        // Join boundaries
        'INNER',
        'LEFT',
        'RIGHT',
        'FULL',
        'JOIN',

        'WHERE',
        'GROUP',
        'HAVING',
        'ORDER',
        'LIMIT',
        'OFFSET'
      ].includes(token.value.toUpperCase())
    }
    
    private parseOrderBy() {
      const clauses: { column: string; direction: 'ASC' | 'DESC' }[] = []

      do {
        const column = this.expectIdentifier()

        let direction: 'ASC' | 'DESC' = 'ASC'

        if (this.match(TokenType.KEYWORD, 'ASC')) 
          direction = 'ASC'
        else if (this.match(TokenType.KEYWORD, 'DESC'))
          direction = 'DESC'

        clauses.push({ column, direction })

      } while (this.match(TokenType.COMMA))

      return clauses
    }
}