import { Injectable } from '@angular/core'
import { Table } from '../models/table.model'
import { Column } from '../models/column.model'
import { FrontFile } from '../models/front-file.model'
import { IndexedDbService } from './indexeddb.service'
import { evaluate } from '../services/parser/expr-eval'
import { SelectColumn, JoinClause, FromClause } from './parser/sql-ast'

@Injectable({
  providedIn: 'root',
})
export class DatabaseService {
  private currentDB = 'DEFAULT'
  private databases = new Set<string>()
  tables = new Map<string, Table>();

  constructor(private store: IndexedDbService) {
    this.init()
  }

  private async init() {
    await this.store.open()
    const saved = await this.store.loadTable('__databases__')

    if (saved) {
      this.databases = new Set(saved)        
    } else {
      this.databases.add('DEFAULT')
      await this.persistDatabases()
    }
    await this.useDatabase('DEFAULT')
  }

  async useDatabase(name: string) {
    if (!this.databases.has(name)) {
      throw new Error(`Database ${name} does not exist`)
    }  
    this.currentDB = name
    this.tables.clear()
  }
  
  private async persistDatabases() {
    await this.store.saveTable('__databases__', [...this.databases])
  }

  async createDatabase(name: string) {
    if (this.databases.has(name)) return
  
    this.databases.add(name)
    await this.persistDatabases()
  }

  async listDatabases(): Promise<string[]> {
    return [...this.databases]
  }  
  
  async saveFile(
    file: File,
    tableName: string,
    columnName: string,
    foreignKeyValue: string
  ) {
    const tableRef = `${this.currentDB}::${tableName}`
    const id = `${tableRef}.${columnName}=${foreignKeyValue}`
  
    const buffer = await file.arrayBuffer()
    const uint8 = new Uint8Array(buffer)
  
    const newFile: FrontFile = {
      name: file.name,
      type: file.type,
      size: file.size,
      data: uint8,
      id,
      tableRef,
      column: columnName,
      foreignKeyValue
    }

    await this.store.saveFile(newFile)

    return newFile
  }
  
  async deleteFile(
    tableName: string, 
    columnName: string, 
    foreignKeyValue: string
  ) {
    const id = `${this.currentDB}::${tableName}.${columnName}=${foreignKeyValue}`  
    await this.store.deleteFile(id)  
    return true
  }

  async loadFile(
    tableName: string, 
    columnName: string, 
    foreignKeyValue: string
  ): Promise<FrontFile> {
    const id = `${this.currentDB}::${tableName}.${columnName}=${foreignKeyValue}`
    const file: FrontFile = await this.store.loadFile(id)

    if(!file)
      throw new Error (`The file '${id}' does not exist`)

    return file
  }

  async loadFilesByTable(tableName: string): Promise<FrontFile[]> {
    const tableRef = `${this.currentDB}::${tableName}`
    const files: FrontFile[] = await this.store.loadFilesByTable(tableRef)
    return files
  }

  async listTables(): Promise<string[]> {
    const prefix = `${this.currentDB}::`
    const tables: string[] = []
  
    await this.store.iterateKeys(key => {
      if (typeof key === 'string' && key.startsWith(prefix)) {
        tables.push(key.replace(prefix, ''))
      }
    })  
    return tables
  }
  
  async dropDatabase(name: string) {
    if (name === 'DEFAULT') {
      throw new Error('Cannot drop DEFAULT database')
    }  
    if (!this.databases.has(name)) return
  
    this.databases.delete(name)
    await this.persistDatabases()  
    // delete all tables belonging to this DB
    await this.store.deleteByPrefix(`${name}::`)
  
    if (this.currentDB === name) {
      await this.useDatabase('DEFAULT')
    }
  }
  
  async createTable(name: string, columns: Column[]) {
    const key = `${this.currentDB}::${name}`
    if (this.tables.has(name)) return
  
    const table = new Table(name, columns, [])
    const saved = await this.store.loadTable(key)
  
    if (saved) Object.assign(table, saved)
  
    this.tables.set(name, table)  // insert into memory
    await this.store.saveTable(key, this.tables.get(name))  // insert into IndexedDB (from memory)
  }
 
  async dropTable(tableName: string): Promise<void> {
    const key = `${this.currentDB}::${tableName}`
    const exists = await this.store.tableExists(key)
  
    if (!exists) {
      throw new Error(`Table '${tableName}' does not exist`)
    }
    await this.store.deleteTable(key)  // remove from IndexedDB
    this.tables.delete(tableName)  // remove from memory
  }

  async renameTable(oldName: string, newName: string): Promise<Table> {
    if (this.tables.has(newName)) {
      throw new Error('Target table already exists')
    }  
    const oldKey = `${this.currentDB}::${oldName}`
    const newKey = `${this.currentDB}::${newName}`  
    const table = await this.table(oldName)  
    table.name = newName  // update table object  
    await this.store.saveTable(newKey, table)  // persist under new key    
    await this.store.deleteByPrefix(oldKey)  // remove old key
    this.tables.delete(oldName)  // update in-memory map
    this.tables.set(newName, table)
  
    return table
  }  
  
  private resolveColumn(row: any, column: string) {
    if (!row) return undefined  
    // direct match (aggregated rows hit here)
    if (column in row) return row[column]  
    // fully-qualified column (a.name)
    if (column.includes('.') && column in row) return row[column]  
    // try suffix match (alias.column)
    const matches = Object.keys(row).filter(k =>
      k.endsWith('.' + column)
    )  
    if (matches.length === 1) return row[matches[0]]  
    if (matches.length > 1) throw new Error(`Ambiguous column '${column}'`)    
  
    return undefined
  }
  
  private processSelectRows(
    rows: any[],
    where?: any,
    columns: SelectColumn[] = [{ type: 'COLUMN', name: '*' }],
    distinct: boolean = false,
    orderBy?: { column: string; direction: 'ASC' | 'DESC' }[],
    limit?: number,
    offset?: number,
    groupBy?: string[],
    having?: any
  ): any[] {

    if (where) {
      rows = rows.filter(row =>
        evaluate(
          where,
          new Proxy(row, {
            get: (target, prop: string) =>
              this.resolveColumn(target, prop)
          })
        ) === true
      )
    }
    
    // GROUP BY
    if (groupBy && groupBy.length > 0) {
      const groups = new Map<string, any[]>()

      for (const row of rows) {
        const key = JSON.stringify(
          groupBy.map(col => this.resolveColumn(row, col))
        )

        if (!groups.has(key)) {
          groups.set(key, [])
        }
        groups.get(key)!.push(row)
      }

      const result: any[] = []

      for (const [, groupRows] of groups) {
        const aggregatedRow: any = {}

        for (const col of columns) {
          // Regular column (must be grouped column)
          if (col.type === 'COLUMN') {
            const key = col.alias ?? col.name
            aggregatedRow[key] = this.resolveColumn(groupRows[0], col.name)
          }
          // Aggregate column
          else {
            const defaultKey =
              col.type.toLowerCase() +
              (col.argument ? '_' + col.argument : '')

            const key = col.alias ?? defaultKey
            aggregatedRow[key] = this.computeAggregate(col, groupRows)
          }
        }
        result.push(aggregatedRow)
      }

      rows = result
      
      if (having) {
        rows = rows.filter(row =>
          evaluate(
            having,
            new Proxy(row, {
              get: (target, prop: string) =>
                this.resolveColumn(target, prop)
            })
          ) === true
        )
      }      
    }

    const hasAggregate = columns.some(
      c => c.type !== 'COLUMN'
    )
    const hasRegularColumn = columns.some(
      c => c.type === 'COLUMN' && c.name !== '*'
    )
    
    if (hasAggregate && hasRegularColumn && !groupBy) {
      throw new Error(
        'Mixing aggregate and non-aggregate columns requires GROUP BY'
      )
    }

    if (hasAggregate && !groupBy) {
      const result: any = {}
    
      for (const col of columns) {    
        if (col.type === 'COLUMN') continue

        const key = col.alias ?? col.type.toLowerCase() + '_' + col.argument
        result[key] = this.computeAggregate(col, rows)
      }
    
      return [result]
    }
    
    // DISTINCT
    if (distinct) {
      const seen = new Set<string>()

      rows = rows.filter(row => {
        const key = JSON.stringify(row)
        if (seen.has(key)) return false
        seen.add(key)
        return true
      })
    }
    
    // ORDER BY
    if (orderBy && orderBy.length > 0) {
      rows = [...rows].sort((a, b) => {
        for (const clause of orderBy) {
          const { column, direction } = clause

          const valA = this.resolveColumn(a, column)
          const valB = this.resolveColumn(b, column)

          if (valA < valB) return direction === 'ASC' ? -1 : 1
          if (valA > valB) return direction === 'ASC' ? 1 : -1
        }
        return 0
      })
    }

    // LIMIT / OFFSET
    if (typeof limit === 'number') {
      const start = offset ?? 0
      const end = start + limit
      rows = rows.slice(start, end)
    }

    if (
      columns.length === 1 &&
      columns[0].type === 'COLUMN' &&
      columns[0].name === '*'
    ) {
      return rows
    }
    
    // projection
    return rows.map(row => {
      const projected: any = {}

      for (const col of columns) {

        if (col.type === 'COLUMN') {
          const outputName = col.alias ?? col.name
          projected[outputName] = this.resolveColumn(row, col.name)
        } else {
          const key =
            col.type.toLowerCase() +
            (col.argument ? '_' + col.argument : '')

          const outputName = col.alias ?? key
          projected[outputName] = row[outputName]
        }
      }
      return projected
    })
  }  

  async select(
    from: FromClause,
    joins?: JoinClause[], 
    where?: any, 
    columns: SelectColumn[] = [{ type: 'COLUMN', name: '*' }], 
    distinct: boolean = false,
    orderBy?: { column: string; direction: 'ASC' | 'DESC' }[],
    limit?: number,
    offset?: number,
    groupBy?: string[],
    having?: any
    ): Promise<any[]> {
  
    const baseTable = await this.table(from.table)
    const baseAlias = from.alias ?? from.table

    let rows = baseTable.rows.map(r =>
      this.prefixRow(r, baseAlias)
    )

    // Apply joins sequentially (chaining)
    for (const join of joins ?? []) {
      const joinTable = await this.table(join.table)
      rows = this.applyJoin(rows, join, joinTable)
    }

    return this.processSelectRows(
      rows,
      where,
      columns,
      distinct,
      orderBy,
      limit,
      offset,
      groupBy,
      having
    )
  }
  
  private applyJoin(
    leftRows: any[],
    join: JoinClause,
    joinTable: Table
  ): any[] {
  
    const joinAlias = join.alias ?? join.table
    const rightRows = joinTable.rows.map(r =>
      this.prefixRow(r, joinAlias)
    )
  
    // CROSS JOIN FIRST
    if (join.type === 'CROSS') {
      const result: any[] = []

      for (const leftRow of leftRows) {
        for (const rightRow of rightRows) {
          result.push({ ...leftRow, ...rightRow })
        }
      }

      return result
    }

    const result: any[] = []
    const matchedRightIndexes = new Set<number>()
  
    for (const leftRow of leftRows) {
  
      let matched = false
  
      for (let rIndex = 0; rIndex < rightRows.length; rIndex++) {
  
        const rightRow = rightRows[rIndex]
  
        const merged = {...leftRow, ...rightRow}
  
        if (evaluate(join.on, merged) === true) {
          matched = true
          matchedRightIndexes.add(rIndex)
          result.push(merged)
        }
      }
  
      // LEFT and FULL need unmatched LEFT rows
      if (!matched && (join.type === 'LEFT' || join.type === 'FULL')) {  
        result.push({
          ...leftRow,
          ...this.buildNullRow(joinAlias, joinTable)
        })
      }
    }
  
    // RIGHT and FULL need unmatched RIGHT rows
    if (join.type === 'RIGHT' || join.type === 'FULL') {
      const nullLeft = this.buildNullFromExisting(leftRows)

      for (let rIndex = 0; rIndex < rightRows.length; rIndex++) {        
        if (!matchedRightIndexes.has(rIndex)) {  
          result.push({
            ...nullLeft,
            ...rightRows[rIndex]
          })
        }
      }
    }
  
    return result
  }

  private buildNullRow(alias: string, table: Table) {
    const nullRow: any = {}
  
    for (const col of table.columns) {
      nullRow[`${alias}.${col.name}`] = null
    }
  
    return nullRow
  }

  private buildNullFromExisting(rows: any[]) {
    const nullRow: any = {}
  
    if (rows.length === 0) return nullRow
  
    for (const key of Object.keys(rows[0])) {
      nullRow[key] = null
    }
  
    return nullRow
  }

  private prefixRow(row: any, prefix: string) {
    const result: any = {}  
    for (const key in row) 
      result[`${prefix}.${key}`] = row[key]  
    return result
  }

  private computeAggregate(
    col: SelectColumn,
    rows: any[]
  ): any {
  
    switch (col.type) {
  
      case 'COUNT': {
        if (col.argument === '*') {
          return rows.length
        }
  
        return rows.filter(r => 
          this.resolveColumn(r, col.argument) !== null).length
      }
  
      case 'SUM': {
        const values = rows
          .map(r => this.resolveColumn(r, col.argument))
          .filter(v => typeof v === 'number')
  
        return values.reduce((acc, v) => acc + v, 0)
      }
  
      case 'AVG': {
        const values = rows
          .map(r => this.resolveColumn(r, col.argument))
          .filter(v => typeof v === 'number')
  
        if (values.length === 0) return null
  
        const sum = values.reduce((acc, v) => acc + v, 0)
        return sum / values.length
      }

      case 'MIN': {
        const values = rows
          .map(r => this.resolveColumn(r, col.argument))
          .filter(v => v !== null && v !== undefined)
  
        if (values.length === 0) return null
  
        return values.reduce((min, v) => (v < min ? v : min))
      }

      case 'MAX': {
        const values = rows
          .map(r => this.resolveColumn(r, col.argument))
          .filter(v => v !== null && v !== undefined)
  
        if (values.length === 0) return null
  
        return values.reduce((max, v) => (v > max ? v : max))
      }
      
      default:
        throw new Error(`Unsupported aggregate type '${(col as any).type}'`)
    }
  }
  
  async insert(tableName: string, row: any): Promise<Table> {
    const table = await this.table(tableName)
    const validRow = this.validateRow(row, table)
    table.insert(validRow)
    await this.persist(tableName)
    return table
  } 

  private validateRow(row: any, table: Table): any {
    const result: any = {}
    const columns: Column[] = table.columns
  
    for (const col of columns) {      
      const value = row[col.name]
  
      // PRIMARY KEY must exist
      if (col.primary &&
        !col.autoIncrement && 
        (value === undefined || value === null)) {
        throw new Error(`Primary key '${col.name}' cannot be null`)
      }
      
      // Default undefined = null
      const finalValue =
        value === undefined
          ? null
          : this.coerceType(value, col.type, col.name)

        if (value === undefined) {
          result[col.name] = null
          continue
        }
  
      result[col.name] = finalValue
    }
    // reject unknown columns
    for (const key of Object.keys(row)) {
      if (!columns.find(c => c.name === key)) {
        throw new Error(`Unknown column '${key}'`)
      }
    }  
    return result
  }
  
  private coerceType(value: any, type: string, columnName: string): any {
    if (value === null) return null

    switch (type) {
      case 'INT': {
        if (typeof value === 'number') {
          if (!Number.isInteger(value)) {
            throw new Error(`Column '${columnName}' expects INT`)
          }
          return value
        }

        if (typeof value === 'string' && /^\d+$/.test(value)) {
          return parseInt(value, 10)
        }

        throw new Error(`Invalid INT value for column '${columnName}'`)
      }

      case 'TEXT': {
        if (typeof value === 'string') return value
        return String(value)
      }

      case 'BLOB': {
        if (value instanceof Uint8Array) return value
        throw new Error(`Column '${columnName}' expects BLOB`)
      }

      default:
        throw new Error(`Unknown column type '${type}'`)
    }
  }

  async persist(name: string) {
    const key = `${this.currentDB}::${name}`
    this.store.saveTable(key, this.tables.get(name))
  }
  
  async table(name: string): Promise<Table> {
    let table = this.tables.get(name)  // try loading table from memory
    if (!table)  // table does not exist in memory
      table = await this.loadTable(name)  // try loading table from disk, i.e., IndexedDB
    return table
  }
  
  async loadTable(name: string): Promise<Table> {
    const key = `${this.currentDB}::${name}`  // tables load from current DB
    const saved = await this.store.loadTable(key)
    if (!saved) {
      throw new Error(`Table ${name} does not exist`)
    }
    const table = new Table(  //initialize a table model from saved table's data
      saved.name,
      saved.columns,
      saved.rows ?? []
    )  
    this.tables.set(name, table)  // add table model initialized from disk to memory
    return table
  }
}