import { normalize } from '../helpers'
import { Expr } from './expr'

type SqlBool = true | false | null

function sqlNot(value: SqlBool): SqlBool {
  if (value === null) return null
  return !value
}

function sqlAnd(a: SqlBool, b: SqlBool): SqlBool {
  if (a === false || b === false) return false
  if (a === null || b === null) return null
  return true
}

function sqlOr(a: SqlBool, b: SqlBool): SqlBool {
  if (a === true || b === true) return true
  if (a === null || b === null) return null
  return false
}

export function evaluate(expr: Expr, row: any): any {
    switch (expr.kind) {
  
      case 'AGGREGATE': {
        const key =
          expr.func.toLowerCase() +
          (expr.argument ? '_' + expr.argument : '')
      
        return row[key]
      }
      
      case 'LITERAL':
        return expr.value
  
      case 'IDENTIFIER': {
        // Direct match first (a.id, b.id)
        if (expr.name in row) {
          return row[expr.name]
        }
      
        // Try resolving unqualified column name
        const matches = Object.keys(row)
          .filter(k => k.endsWith(`.${expr.name}`))
      
        if (matches.length === 1) {
          return row[matches[0]]
        }
      
        if (matches.length > 1) {
          throw new Error(`Ambiguous column: ${expr.name}`)
        }
      
        return undefined
      }        
  
      case 'UNARY': {
        const value = evaluate(expr.right, row)
  
        switch (expr.operator) {
          case 'NOT':
            return sqlNot(evaluate(expr.right, row) as SqlBool)
  
          case '-':
            return -value
  
          default:
            throw new Error(`Unsupported unary operator "${expr.operator}"`)
        }
      }
  
      case 'IS_NULL': {
        const value = evaluate(expr.expression, row)
        const isNull = value === null || value === undefined
        return expr.not ? !isNull : isNull
      }
      
      case 'BINARY': {
        const left = normalize(evaluate(expr.left, row))
        const right = normalize(evaluate(expr.right, row))
  
        switch (expr.operator) {  
          // comparison
          case '=':
          case '!=':
          case '<':
          case '<=':
          case '>':
          case '>=': {
            if (left === null || right === null) return null
          
            switch (expr.operator) {
              case '=':  return left === right
              case '!=': return left !== right
              case '<':  return left < right
              case '<=': return left <= right
              case '>':  return left > right
              case '>=': return left >= right
            }
          }  

          case 'LIKE':
            if (left === null || right === null) return null
          
            // safe, escape regex characters first
            const escaped = String(right).replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
            const pattern = escaped.replace(/%/g, '.*').replace(/_/g, '.')          
            const regex = new RegExp(`^${pattern}$`, 'i')

            return regex.test(String(left))          
  
          // logical
          case 'AND':
            return sqlAnd(left as SqlBool, right as SqlBool)

          case 'OR':
            return sqlOr(left as SqlBool, right as SqlBool)
  
          // arithmetic
          case '+': return left + right
          case '-': return left - right
          case '*': return left * right
          case '/': return left / right
  
          default:
            throw new Error(`Unsupported operator "${expr.operator}"`)
        }
      }

      case 'IN': {
        const leftValue = evaluate(expr.left, row)
        const values = expr.values.map(v => evaluate(v, row))

        if (leftValue === null) return null

        let found = false
        let hasNull = false

        for (const v of values) {
          if (v === null) {
            hasNull = true
          } else if (v === leftValue) {
            found = true
          }
        }

        if (found) return true
        if (hasNull) return null
        return false
      }
      
      case 'BETWEEN': {
        const value = evaluate(expr.value, row)
        const lower = evaluate(expr.lower, row)
        const upper = evaluate(expr.upper, row)

        if (value === null || lower === null || upper === null) 
          return null        
        return value >= lower && value <= upper        
      }
      
      case 'GROUP':
          return evaluate(expr.expression, row)
  
      default:
        throw new Error(`Unknown WHERE expression. There might be a syntax error in your query!`)
    }
}