import { Component } from '@angular/core'
import { SqlConsoleComponent } from './sql-console/sql-console.component'

@Component({
  selector: 'lib-front-sql',
  imports: [SqlConsoleComponent],
  template: `
  <div class="main">
   <div class="content">
    <div class="left-side">
     <app-sql-console />
    </div>
   </div>
  </div>
  `,
  styles: `
  :root {

    /* =========================
       HACKER CORE COLORS
    ========================== */
  
    --terminal-bg: #000000;
    --terminal-panel: #001a11;
    --terminal-border: #003322;
  
    --terminal-text-primary: #00ff88;
    --terminal-text-bright: #00ffaa;
    --terminal-text-dim: #004422;
    --terminal-text-soft: #66ff66;
  
    --terminal-error-bg: #220000;
    --terminal-error-border: #660000;
    --terminal-error-text: #ff4444;
  
    /* Glow */
    --terminal-glow-soft: 0 0 6px rgba(0, 255, 136, 0.4);
    --terminal-glow-strong: 0 0 12px rgba(0, 255, 136, 0.7);
  
    /* Typography */
    --terminal-font: 'Courier New', monospace;
  
  }

  .main {
    width: 100%;
    min-height: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
    padding: 1rem;
    box-sizing: inherit;
    position: relative;
  }
  
  .content {
    display: flex;
    justify-content: space-around;
    width: 100%;
    max-width: 90%;
    margin-bottom: 3rem;
  }

  @media screen and (max-width: 650px) {
    .content {
      flex-direction: column;
      width: max-content;
    }
  }
  `,
})
export class FrontSql {

}
