export enum TokenType {
  KEYWORD = 'KEYWORD',
  IDENTIFIER = 'IDENTIFIER',
  NUMBER = 'NUMBER',
  STRING = 'STRING',
  OPERATOR = 'OPERATOR',
  NULL = 'NULL',
  COMMA = 'COMMA',
  DOT = 'DOT',
  STAR = 'STAR',
  LPAREN = 'LPAREN',
  RPAREN = 'RPAREN',

  EOF = 'EOF'
}

export interface Token {
  type: TokenType
  value: any
  start: number
  end: number
}  